#include <iostream>
using namespace std;

int main() {
    long long x, y;
    cin >> x >> y;

    if (x == 0 && y == 0) {
        cout << 0 << '\n';
        return 0;
    }

    long long sx = 0, sy = 0;
    long long plen = 0;
    bool hdir = true, hright = true;
    long long turns = 0;

    while (true) {
        ++turns;

        if (hdir) {
            ++plen;

            if (hright) {
                if (sy == y && x > sx && sx + plen >= x) break;
                sx += plen;
            } else {
                if (sy == y && x < sx && sx - plen <= x) break;
                sx -= plen;
            }

            hright = !hright;
        } else {
            if (!hright) {
                if (sx == x && y > sy && sy + plen >= y) break;
                sy += plen;
            } else {
                if (sx == x && y < sy && sy - plen <= y) break;
                sy -= plen;
            }
        }

        hdir = !hdir;
    }

    cout << turns - 1 << '\n';
    return 0;
}

